class Gradebook:
    def __init__(self) -> None:
        self._assignments = {}  # name -> (weight, kind)
        self._grades = {}       # student -> {assignment: grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError("kind must be 'homework' or 'quiz'")
        self._assignments[name] = (weight, kind)
        # initialize grade slot for existing students? not needed, handled at avg time

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment}")
        self._grades.setdefault(student, {})[assignment] = float(grade)

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        # Determine which quizzes exist and which to drop
        quiz_names = [n for n, (_, k) in self._assignments.items() if k == "quiz"]
        dropped_quiz = None
        if len(quiz_names) > 1:
            # Only consider quizzes actually recorded? Requirement says "more than one quiz" grade.
            # Interpretation: if student has more than one quiz grade, drop the lowest quiz grade.
            recorded_quizzes = [q for q in quiz_names if q in student_grades]
            if len(recorded_quizzes) > 1:
                dropped_quiz = min(recorded_quizzes, key=lambda q: student_grades[q])

        total_weight = 0.0
        weighted_sum = 0.0
        for name, (weight, kind) in self._assignments.items():
            if name == dropped_quiz:
                continue
            grade = student_grades.get(name, 2.0)
            weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0:
            return 0.0
        return round(weighted_sum / total_weight, 2)
